update public.learning_paths
set
  title = 'First Aid / CPR / Emergency Response',
  goal = 'First Aid / CPR / Emergency Response',
  summary = 'This course prepares kinesiology students to recognize emergencies, protect the scene, activate emergency services, perform primary and secondary assessment, provide adult, child, and infant CPR, use an AED, manage choking, control bleeding, care for shock, respond to fractures, sprains, head/neck/spine injuries, heat and cold emergencies, and participate in emergency action plans. The course emphasizes hands-on practice, sport and exercise settings, team communication, documentation, special populations, certification readiness, and reflective improvement.',
  data = $faerjson${"slug": "first-aid-cpr-emergency-response", "title": "First Aid / CPR / Emergency Response", "description": "This course prepares kinesiology students to recognize emergencies, protect the scene, activate emergency services, perform primary and secondary assessment, provide adult, child, and infant CPR, use an AED, manage choking, control bleeding, care for shock, respond to fractures, sprains, head/neck/spine injuries, heat and cold emergencies, and participate in emergency action plans. The course emphasizes hands-on practice, sport and exercise settings, team communication, documentation, special populations, certification readiness, and reflective improvement.", "topics": [{"id": "22bd7c60-3d04-444e-b491-a4f757ecad56", "type": "topic", "title": "Responder Role, Legal/Ethical Duties, and Emergency Mindset", "description": "Frame first aid as calm, competent action within scope, consent, safety, and duty-to-respond expectations.", "children": [{"id": "59b56fab-2767-4d08-99b7-5ea307f51701", "type": "subtopic", "title": "Scope and role clarity", "description": "Students learn what a trained lay responder or kinesiology professional should and should not do.", "children": [{"id": "7b00a410-e0c6-403e-afc1-246c253bc49b", "type": "concept", "title": "Recognizing emergencies"}, {"id": "b5e86325-8f0c-44ff-bbc0-74302c9bede5", "type": "concept", "title": "Providing care within training"}, {"id": "a006a812-c9e5-4ca3-b7bf-88e078f25571", "type": "concept", "title": "Calling EMS"}, {"id": "2ce337e9-b8aa-45de-b4c8-5344c0963d6d", "type": "concept", "title": "Handing off to professionals"}]}, {"id": "4431a8ff-b59b-4c02-9844-1df1969a3104", "type": "subtopic", "title": "Consent and legal protection", "description": "Students learn the basic legal/ethical rules that shape emergency care.", "children": [{"id": "089a2d0c-823a-40a3-b5b2-50a7b4f6bc45", "type": "concept", "title": "Expressed consent"}, {"id": "7828ba1b-203c-4b3b-9c43-0f2425d3a400", "type": "concept", "