": "Gloves"}, {"id": "59002224-4bf1-401b-b651-9268fe4a78a1", "type": "concept", "title": "CPR mask or face shield"}, {"id": "58a37059-d8a6-4bdb-8f29-d8804a76f56b", "type": "concept", "title": "Hand hygiene"}, {"id": "9783890d-bf52-4f54-a791-f7c627a5cab4", "type": "concept", "title": "Sharps and biohazard awareness"}]}, {"id": "eafd19fd-e06f-4430-bbd5-889cacc9f04e", "type": "subtopic", "title": "Activating help", "description": "Students learn to call for help early and communicate useful information.", "children": [{"id": "824b9a4a-039d-4c18-8290-cb733e900b2b", "type": "concept", "title": "EMS activation"}, {"id": "27f1656a-c684-4d2f-b86f-37098c377444", "type": "concept", "title": "Location and access points"}, {"id": "b78a6ad6-1644-4c76-bf27-4726c7e33011", "type": "concept", "title": "Patient condition"}, {"id": "05167358-4f1d-415c-9280-63fe99033899", "type": "concept", "title": "Sending someone for AED and first aid kit"}]}]}, {"id": "3946705e-6757-46f5-b3b4-aea39a255c62", "type": "topic", "title": "Primary Assessment, Secondary Assessment, and Vital Signs", "description": "Build a repeatable assessment sequence for identifying life threats and gathering useful information.", "children": [{"id": "69a3d09a-a42a-4f42-8b00-87f68668ee80", "type": "subtopic", "title": "Primary assessment", "description": "Students learn a fast sequence for finding life threats.", "children": [{"id": "260ea8da-374a-4c09-a586-a83a87bfde9d", "type": "concept", "title": "Responsiveness"}, {"id": "4bbd0644-3958-4901-a063-5d1365bd1978", "type": "concept", "title": "Airway"}, {"id": "281273f1-1a6b-44c5-8a4a-8d4d156ea6f5", "type": "concept", "title": "Breathing"}, {"id": "27f8e0ab-fbbf-40f9-b51e-fd32fc065a1c", "type": "concept", "title": "Circulation and severe bleeding"}]}, {"id": "995e209a-6f20-487f-9ca1-a76476eff27f", "type": "subtopic", "title": "Secondary assessment", "description": "Students gather more detail once immediate threats are addressed.", "children": [{"id": "52190b77-6fdf-49c1-8250-f92e4330999e", "type": "concept", "title": "SAMPLE history"}, {"id": "78a96c19-add9-425a-975f-040ddea433c7", "type": "concept", "title": "Focused exam"}, {"id": "69026543-4640-407d-b51e-bcfbc6c922d6", "type": "concept", "title": "Pain and mechanism of injury"}, {"id": "332b3ccd-b1c0-4116-abba-73ab05d28a24", "type": "concept", "title": "Allergies and medications"}]}, {"id": "abe63bc5-acd0-4d36-acb6-991ec08fccea", "type": "subtopic", "title": "Vital signs and monitoring", "description": "Students learn simple measures that reveal deterioration or improvement.", "children": [{"id": "2190c90c-fb8a-465f-b680-8058ba02c941", "type": "concept", "title": "Pulse"}, {"id": "37382522-9fc6-4c17-acec-80af799fc804", "type": "concept", "title": "Breathing rate"}, {"id": "e66d874b-7280-4d1f-aa5f-7f9159b17e07", "type": "concept", "title": "Skin signs"}, {"id": "69176554-b306-4236-a4fb-681bb7567993", "type": "concept", "title": "Level of consciousness"}]}]}, {"id": "989f2d55-2650-4763-bb5d-997eac96a089", "type": "topic", "title": "Adult, Child, and Infant CPR Foundations", "description": "Develop high-quality CPR skills across age groups using current BLS-style priorities and feedback.", "children": [{"id": "2ac8051c-b94a-43cc-a5ce-04e83f1529e0", "type": "subtopic", "title": "High-quality compressions", "description": "Students learn the physical skill that most directly affects survival in cardiac arrest.", "children": [{"id": "069f17c7-acb7-4793-b12d-72b5bc40efb5", "type": "concept", "title": "Compression depth"}, {"id": "80c4683c-9f44-4656-958e-76d95d42ffb3", "type": "concept", "title": "Compression rate"}, {"id": "ddacb7f2-5f84-438d-91d9-4320dc0b7758", "type": "concept", "title": "Full recoil"}, {"id": "7115be62-039b-4de1-9ce3-13c7cf9f0b15", "type": "concept", "title": "Minimizing interruptions"}]}, {"id": "4f9d8348-d805-43c9-945e-0a18d7de84a8", "type": "subtopic", "title": "Age-specific CPR", "description": "Students adapt technique for adults, children, and infants.", "ch